<?php
chdir('../..'); include('./include/auth.php'); include_once($config['base_path'].'/plugins/icct_inventory/lib/functions.php'); include_once($config['base_path'].'/plugins/icct_inventory/include/nav.php');
$manage=icct_inv_can_manage(); $action=icct_inv_req('action');
if($_SERVER['REQUEST_METHOD']==='POST' && $manage){
 if($action==='save'){$res=icct_inv_save_segment(icct_inv_req_int('id'),['name'=>icct_inv_req('name'),'cidr'=>icct_inv_req('cidr'),'description'=>icct_inv_req('description'),'enabled'=>icct_inv_req('enabled')==='on']); if($res['ok']){raise_message('seg_saved','Segment saved.',MESSAGE_LEVEL_INFO);header('Location: '.$config['url_path'].'plugins/icct_inventory/segments.php');exit;} raise_message('seg_err',$res['error'],MESSAGE_LEVEL_ERROR);}
 if($action==='delete'){$res=icct_inv_delete_segment(icct_inv_req_int('id')); if($res['ok'])raise_message('seg_del','Segment deleted.',MESSAGE_LEVEL_INFO); else raise_message('seg_err',$res['error'],MESSAGE_LEVEL_ERROR); header('Location: '.$config['url_path'].'plugins/icct_inventory/segments.php');exit;}
}
$edit=icct_inv_req_int('edit'); $row=$edit?icct_inv_get_segment($edit):[]; $data=icct_inv_get_segments(false); $plugin_url=$config['url_path'].'plugins/icct_inventory';
top_header(); print '<link rel="stylesheet" href="'.html_escape($plugin_url.'/css/icct_inventory.css').'">'; print '<div class="icct-inv-page">'; icct_inventory_nav('segments');
if($manage){html_start_box($row?'Edit Segment':'Create Segment','100%',false,3,'center',''); print get_message_html(); form_start('segments.php','seg_form'); print '<input type="hidden" name="action" value="save"><input type="hidden" name="id" value="'.(int)($row['id']??0).'">'; print '<div class="icct-form-grid"><label>Name *</label><input name="name" required value="'.icct_inv_h($row['name']??'').'"><label>CIDR / Subnet</label><input name="cidr" placeholder="10.10.20.0/24" value="'.icct_inv_h($row['cidr']??'').'"><label>Description</label><input name="description" value="'.icct_inv_h($row['description']??'').'"><label>Enabled</label><label><input type="checkbox" name="enabled" value="on" '.(!$row||($row['enabled']??'')==='on'?'checked':'').'> Enabled</label><div class="icct-actions"><a class="button" href="segments.php">New</a><button type="submit">Save</button></div></div>'; form_end(); html_end_box(true,true);}
html_start_box('Segments','100%',false,3,'center',''); html_header(['Name','CIDR','Description','Enabled','Actions']); $i=0; foreach($data as $s){form_alternate_row('seg_'.$s['id'],true); form_selectable_cell(icct_inv_h($s['name']),$i); form_selectable_cell(icct_inv_h($s['cidr'] ?: '—'),$i); form_selectable_cell(icct_inv_h($s['description']),$i); form_selectable_cell(($s['enabled']==='on'?'Yes':'No'),$i); $a=$manage?'<a href="segments.php?edit='.(int)$s['id'].'">Edit</a>':''; if($manage){$a.=' <form method="post" style="display:inline"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="'.(int)$s['id'].'"><button type="submit" onclick="return confirm(\'Delete this segment?\')">Delete</button></form>';} form_selectable_cell($a,$i); form_end_row(); $i++;} if(!$data)print '<tr><td colspan="5"><em>No segments configured.</em></td></tr>'; html_end_box(true,true); print '</div>'; bottom_footer();
